import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

#define THREADS 256

__global__ void compute_stats_kernel(const float* __restrict__ x, float* __restrict__ mean, float* __restrict__ var,
                                      int N, int C, int H, int W) {
    int c = blockIdx.x;
    int HW = H * W;
    long count = (long)N * HW;
    float sum = 0.0f;
    float sumsq = 0.0f;
    for (long idx = threadIdx.x; idx < count; idx += blockDim.x) {
        long n = idx / HW;
        long hw = idx % HW;
        long offset = (n * (long)C + c) * (long)HW + hw;
        float val = x[offset];
        sum += val;
        sumsq += val * val;
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        sum += __shfl_down_sync(mask, sum, off);
        sumsq += __shfl_down_sync(mask, sumsq, off);
    }
    __shared__ float warp_sum[THREADS / 32];
    __shared__ float warp_sumsq[THREADS / 32];
    int warp_id = threadIdx.x >> 5;
    int lane = threadIdx.x & 31;
    if (lane == 0) {
        warp_sum[warp_id] = sum;
        warp_sumsq[warp_id] = sumsq;
    }
    __syncthreads();
    if (warp_id == 0) {
        int num_warps = blockDim.x >> 5;
        float s = (lane < num_warps) ? warp_sum[lane] : 0.0f;
        float sq = (lane < num_warps) ? warp_sumsq[lane] : 0.0f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            s += __shfl_down_sync(mask, s, off);
            sq += __shfl_down_sync(mask, sq, off);
        }
        if (lane == 0) {
            float m = s / (float)count;
            float v = sq / (float)count - m * m;
            mean[c] = m;
            var[c] = v;
        }
    }
}
__global__ void compute_stats_kernel_vec4(const float4* __restrict__ x4, float* __restrict__ mean, float* __restrict__ var,
                                           int N, int C, long HW_vec) {
    int c = blockIdx.x;
    long count_vec = (long)N * HW_vec;
    long count = count_vec * 4;
    float sum = 0.0f;
    float sumsq = 0.0f;
    for (long idx = threadIdx.x; idx < count_vec; idx += blockDim.x) {
        long n = idx / HW_vec;
        long hw = idx % HW_vec;
        long offset = (n * (long)C + c) * HW_vec + hw;
        float4 v = x4[offset];
        sum += v.x + v.y + v.z + v.w;
        sumsq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        sum += __shfl_down_sync(mask, sum, off);
        sumsq += __shfl_down_sync(mask, sumsq, off);
    }
    __shared__ float warp_sum[THREADS / 32];
    __shared__ float warp_sumsq[THREADS / 32];
    int warp_id = threadIdx.x >> 5;
    int lane = threadIdx.x & 31;
    if (lane == 0) {
        warp_sum[warp_id] = sum;
        warp_sumsq[warp_id] = sumsq;
    }
    __syncthreads();
    if (warp_id == 0) {
        int num_warps = blockDim.x >> 5;
        float s = (lane < num_warps) ? warp_sum[lane] : 0.0f;
        float sq = (lane < num_warps) ? warp_sumsq[lane] : 0.0f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            s += __shfl_down_sync(mask, s, off);
            sq += __shfl_down_sync(mask, sq, off);
        }
        if (lane == 0) {
            float m = s / (float)count;
            float v = sq / (float)count - m * m;
            mean[c] = m;
            var[c] = v;
        }
    }
}

__global__ void bn_forward_kernel(const float* __restrict__ x, float* __restrict__ y,
                                   const float* __restrict__ scale, const float* __restrict__ shift,
                                   int N, int C, int H, int W) {
    long total = (long)N * C * H * W;
    long HW = (long)H * W;
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total; idx += (long)blockDim.x * gridDim.x) {
        int c = (int)((idx / HW) % C);
        y[idx] = x[idx] * scale[c] + shift[c];
    }
}
__global__ void bn_forward_kernel_vec4(const float4* __restrict__ x4, float4* __restrict__ y4,
                                        const float* __restrict__ scale, const float* __restrict__ shift,
                                        long total_vec, long HW_vec, int C) {
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total_vec; idx += (long)blockDim.x * gridDim.x) {
        int c = (int)((idx / HW_vec) % C);
        float s = scale[c];
        float sh = shift[c];
        float4 xv = x4[idx];
        float4 yv;
        yv.x = xv.x * s + sh;
        yv.y = xv.y * s + sh;
        yv.z = xv.z * s + sh;
        yv.w = xv.w * s + sh;
        y4[idx] = yv;
    }
}
torch::Tensor batch_norm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                                  torch::Tensor running_mean, torch::Tensor running_var,
                                  bool training, double momentum, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    x = x.contiguous();
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    auto y = torch::empty_like(x);
    torch::Tensor mean, var;
    if (training) {
        mean = torch::empty({C}, x.options());
        var = torch::empty({C}, x.options());
        int threads = THREADS;
        int blocks = C;
        size_t shared_mem = 0;
        long HW_total = (long)H * W;
        if ((HW_total % 4 == 0) &&
            (reinterpret_cast<uintptr_t>(x.data_ptr<float>()) % 16 == 0)) {
            long HW_vec = HW_total / 4;
            compute_stats_kernel_vec4<<<blocks, threads, shared_mem>>>(
                reinterpret_cast<const float4*>(x.data_ptr<float>()), mean.data_ptr<float>(), var.data_ptr<float>(),
                N, C, HW_vec
            );
        } else {
            compute_stats_kernel<<<blocks, threads, shared_mem>>>(
                x.data_ptr<float>(), mean.data_ptr<float>(), var.data_ptr<float>(),
                N, C, H, W
            );
        }
        long count = (long)N * H * W;
        auto unbiased_var = var * ((float)count / (float)(count - 1));
        running_mean.mul_(1.0 - momentum).add_(mean * momentum);
        running_var.mul_(1.0 - momentum).add_(unbiased_var * momentum);
    } else {
        mean = running_mean;
        var = running_var;
    }
    auto scale = (weight * torch::rsqrt(var + eps)).contiguous();
    auto shift = (bias - mean * scale).contiguous();
    long total = (long)N * C * H * W;
    long HW = (long)H * W;
    int threads2 = 256;
    if ((HW % 4 == 0) && (total % 4 == 0) &&
        (reinterpret_cast<uintptr_t>(x.data_ptr<float>()) % 16 == 0) &&
        (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0)) {
        long total_vec = total / 4;
        long HW_vec = HW / 4;
        long blocks2_l = (total_vec + threads2 - 1) / threads2;
        int blocks2 = (int)(blocks2_l > 65535 ? 65535 : blocks2_l);
        bn_forward_kernel_vec4<<<blocks2, threads2>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            scale.data_ptr<float>(), shift.data_ptr<float>(),
            total_vec, HW_vec, C
        );
    } else {
        long blocks2_l = (total + threads2 - 1) / threads2;
        int blocks2 = (int)(blocks2_l > 65535 ? 65535 : blocks2_l);
        bn_forward_kernel<<<blocks2, threads2>>>(
            x.data_ptr<float>(), y.data_ptr<float>(),
            scale.data_ptr<float>(), shift.data_ptr<float>(),
            N, C, H, W
        );
    }
    return y;
}
